#include "stdafx.h"#include "HcdDebugApp.h"#include "PrjView.h"#include "HcdDebug.h"#include <macros/AutoRestore.h>#include <vector>#include "FindByName.h"#include <macros/StrHelps.h>// KPrjViewIMPLEMENT_DYNCREATE(KPrjView, CTreeView)KPrjView::KPrjView(): m_pCtrl( NULL ), m_bInited( false ), m_bSelectFromMe( false ){}KPrjView::~KPrjView(){}KHcdDebugDoc* KPrjView::GetDocument(){  ASSERT(m_pDocument->IsKindOf(RUNTIME_CLASS(KHcdDebugDoc)));  return (KHcdDebugDoc*)m_pDocument;}BEGIN_MESSAGE_MAP(KPrjView, CTreeView)  ON_MESSAGE( WM_USER, OnWmUser)  //ON_COMMAND(ID_FIND, &KPrjView::OnFind)  ON_NOTIFY_REFLECT(TVN_SELCHANGED, &KPrjView::OnTvnSelchanged)END_MESSAGE_MAP()// KPrjView diagnostics#ifdef _DEBUGvoid KPrjView::AssertValid() const{	CTreeView::AssertValid();}#ifndef _WIN32_WCEvoid KPrjView::Dump(CDumpContext& dc) const{	CTreeView::Dump(dc);}#endif#endif //_DEBUG// KPrjView message handlersBOOL KPrjView::Create(LPCTSTR lpszClassName, LPCTSTR lpszWindowName, DWORD dwStyle, const RECT& rect, CWnd* pParentWnd, UINT nID, CCreateContext* pContext){  dwStyle |= TVS_HASBUTTONS | TVS_HASLINES | TVS_LINESATROOT | TVS_SHOWSELALWAYS | TVS_TRACKSELECT | WS_TABSTOP;    BOOL b = CTreeView::Create(lpszClassName, lpszWindowName, dwStyle, rect, pParentWnd, nID, pContext);  m_pCtrl = &GetTreeCtrl();  m_imgList.Create(IDB_BITMAP1, 20, 0, RGB(166,202,240));  m_pCtrl->SetImageList(&m_imgList,TVSIL_NORMAL);  return b;}LRESULT KPrjView::OnWmUser( WPARAM wParam, LPARAM lParam ){  if( !m_bInited )  {    m_NotifierSelectedContour = GetDocument()->GetEventNotifier( eSelectedPage );    m_bInited = true;    IHcdDrawable ** pp = GetDocument()->m_ppCtrls;    if( !pp )      return 0L;    for( size_t s=0, N(GetDocument()->m_cCtrls); s<N; ++s )    {      FillTree( TVI_ROOT, pp[s] );    }  }  return 1L;}void KPrjView::FillTree( HTREEITEM parent, IHcdDrawable *entry ){  if( !entry )    return;  HTREEITEM hCurRoot = m_pCtrl->InsertItem( entry->GetTreeName(), parent );  m_pCtrl->SetItemData( hCurRoot, (DWORD_PTR)entry );  size_t c = entry->GetChild( NULL, 0 );  if( !c )    return;  std::vector<IHcdDrawable*> buf;  buf.resize( c );  c = entry->GetChild( &buf.at(0), buf.size() );  for( size_t i=0; i<c; ++i )  {    FillTree( hCurRoot, buf.at(i) );  }}void KPrjView::OnFind(){  KFindByName dlgFind( GetDocument() );  if( dlgFind.DoModal() != IDOK )    return;  char elements[10][128] = {};  int C = SplitString( dlgFind.m_ContourFileName, elements, '\\', false );  HTREEITEM hItem = m_pCtrl->GetNextItem( TVI_ROOT, TVGN_ROOT );  //Select( hItem, C, elements );}void KPrjView::OnTvnSelchanged(NMHDR *pNMHDR, LRESULT *pResult){  *pResult = 0;  if( !m_NotifierSelectedContour )    return;  TAutoRestore<bool> me( m_bSelectFromMe );  m_bSelectFromMe = true;  LPNMTREEVIEW pNMTreeView = reinterpret_cast<LPNMTREEVIEW>(pNMHDR);  if( pNMTreeView->action==1 )  {    HTREEITEM hItem = pNMTreeView->itemNew.hItem;    DWORD_PTR fl = m_pCtrl->GetItemData(hItem);    if( fl )    {      IHcdDrawable *pDr = (IHcdDrawable*)fl;      m_NotifierSelectedContour->DoNotify( eSelectedPage, pDr );    }    else       m_NotifierSelectedContour->DoNotify( eSelectedPage, NULL );  }}